/* Standalone, browser-local ordering demo. No dispatch, payment or merchant integration. */
'use strict';
const q=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const peso=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',maximumFractionDigits:0}).format(n);
const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('cm-order-'+key))??fallback}catch{return fallback}};
function persist(key,value){try{localStorage.setItem('cm-order-'+key,JSON.stringify(value));return true}catch{notify('Storage is unavailable. Keep this tab open to retain your demo.');return false}}
const symbols={bike:'M8 17a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM23 17a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM5 17l5-8h6l4 8M8 17h7l2-6M7 6h5M16 4h3l2 5',trike:'M7 18a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM23 18a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM4 18l4-9h4l3 9M8 9V5h11l3 8v5H7M13 5v13M13 12h8',food:'M4 3v7h5V3M6.5 3v18M18 3v18M18 3c-5 5-5 10 0 10',bag:'M4 7h16l1 14H3L4 7Zm4 0V5a4 4 0 0 1 8 0v2',box:'m3 7 9-5 9 5v11l-9 4-9-4V7Zm0 0 9 5 9-5M12 12v10M7 4l10 5',bolt:'m13 2-9 12h7l-1 8L21 9h-8l1-7',home:'m3 10 9-7 9 7v11h-7v-7h-4v7H3V10',orders:'M6 3h12v19l-3-2-3 2-3-2-3 2V3Zm3 5h6M9 12h6',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 22v-3a8 8 0 0 1 16 0v3',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M4 12h16m-6-6 6 6-6 6',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0Zm-2 4 7 7',check:'m5 12 4 4L19 6'};
const svg=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${symbols[n]||symbols.bag}"/></svg>`;
const foodImage='assets/filipino-comfort-food.webp';
const stores=[
 {id:'jollibee',name:'Jollibee',tag:'Filipino fast-food favorites',type:'food',category:'Chicken',image:foodImage,initial:'J',tone:'red',note:'Illustrative demo menu. Not an affiliated or live Jollibee store.',items:[['chicken','Crispy chicken & rice',149,'Golden fried chicken, steamed rice and gravy.'],['spaghetti','Pinoy-style spaghetti',89,'Sweet-style tomato sauce with a savory topping.'],['chicken-combo','Chicken & spaghetti plate',199,'A comforting combination for your merienda.'],['iced-tea','Calamansi iced tea',55,'A refreshing citrus cooler.']]},
 {id:'aling-neneng',name:'Aling Neneng’s Sari-Sari Store',tag:'Your neighborhood essentials',type:'grocery',category:'Sari-sari',image:'assets/aling-neneng-demo.webp',initial:'AN',tone:'green',note:'A fictional neighborhood store created for this demo.',items:[['rice','Bigas · 1 kg',60,'A pantry staple, packed for your everyday meals.'],['eggs','Fresh eggs · 6 pieces',65,'For breakfast and everything in between.'],['coffee','Coffee sachets · 5 pack',45,'Your little morning pick-me-up.'],['noodles','Instant noodles · 3 pack',48,'Easy comfort for a busy day.']]},
 {id:'kusina',name:'Kusina ni Lola',tag:'Lutong bahay, made with care',type:'food',category:'Lutong bahay',image:'assets/service-food.webp',initial:'KL',tone:'ochre',note:'A fictional carinderia. Photos and menus are illustrative.',items:[['adobo','Chicken adobo rice meal',129,'Soy-vinegar chicken with warm steamed rice.'],['sinigang','Sinigang rice meal',149,'A comforting sour broth with vegetables and rice.'],['lumpia','Lumpiang shanghai · 6 pieces',85,'Crisp little bites, perfect for sharing.'],['rice-extra','Extra rice',25,'A little extra for a good meal.']]},
 {id:'kape',name:'Kape sa Kanto',tag:'Good coffee. A slower moment.',type:'food',category:'Coffee & merienda',image:'assets/kape-merienda-demo.webp',initial:'KK',tone:'brown',note:'A fictional local café. Sample menu and prices only.',items:[['latte','Iced Spanish latte',115,'Espresso, milk and a little sweetness.'],['americano','Iced Americano',85,'Bold, refreshing and straightforward.'],['pandesal','Pandesal · 6 pieces',50,'Soft neighborhood bakery favorites.'],['turon','Turon · 3 pieces',60,'Banana, crisp wrapper and caramelized sugar.']]},
 {id:'palengke',name:'Suki Fresh Market',tag:'Fresh picks for your kitchen',type:'grocery',category:'Fresh produce',image:'assets/service-grocery.webp',initial:'SF',tone:'green',note:'A fictional market stall. Availability and prices are examples.',items:[['veg','Sinigang vegetable bundle',95,'A mix of everyday vegetables for your pot.'],['banana','Saging · 1 kg',90,'Fresh fruit for the whole family.'],['tomato','Tomatoes · 500 g',55,'For your everyday cooking.'],['milk','Fresh milk · 1 L',105,'A fridge essential.']]}
];
const productIds=new Set(stores.flatMap(store=>store.items.map(item=>item[0])));
const productImage=id=>productIds.has(id)?'assets/menu/'+id+'.webp':foodImage;
let cart=load('cart',[]),orders=load('orders',[]),delivery=load('address','Quezon City · demo area'),profile=load('profile',null),serviceDraft=load('service-draft',null);
let category='all',search='';
const subtotal=()=>cart.reduce((sum,item)=>sum+item.price*item.qty,0);
const itemCount=()=>cart.reduce((sum,item)=>sum+item.qty,0);
function notify(message){q('#notification').textContent=message;q('#notification').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>q('#notification').classList.remove('show'),3500)}
function shell(content,active='home'){
 q('#app').innerHTML=`<aside class="sidebar"><a class="identity" href="#/"><img src="assets/cartman-app-icon.webp" width="48" height="48" alt="Cartman PH"><span>CARTMAN <em>PH</em><small>ORDER ONLINE</small></span></a><nav aria-label="Order app navigation">${[['home','/','Explore'],['orders','/orders','My orders'],['user','/account','Your profile']].map(([i,url,t])=>`<a href="#${url}" ${active===i?'aria-current="page"':''}>${svg(i)}<span>${t}</span></a>`).join('')}</nav><div class="sidebar-bottom"><a href="/">← Back to Cartman</a></div></aside><div class="app-body"><header class="topbar"><a class="mobile-order-brand" href="#/" aria-label="Cartman PH home"><img src="assets/cartman-app-icon.webp" alt="" width="32" height="32"></a><button class="address-button" id="address-open">${svg('pin')}<span><small>DELIVER TO</small><strong>${esc(delivery)}</strong></span><span>⌄</span></button><div class="top-actions"><label class="order-appearance-label"><span class="sr-only">Appearance</span><select class="order-appearance" data-appearance-select aria-label="Appearance">${Object.entries(window.CartmanAppearance.choices).map(([value,choice])=>`<option value="${value}" ${window.CartmanAppearance.current()===value?'selected':''}>${choice.label}</option>`).join('')}</select></label><button class="cart-toggle" id="basket-open" aria-label="Open basket, ${itemCount()} ${itemCount()===1?'item':'items'}">${svg('bag')}<span class="basket-label">Basket</span><b>${itemCount()}</b></button></div></header><main id="main" tabindex="-1">${content}</main><footer class="app-footer">Demo experience · Sample stores, images, menus, prices and delivery times. No merchant affiliation, payment or dispatch. <a href="/">About Cartman PH ↗</a></footer></div><dialog id="app-dialog"></dialog>`;
 document.querySelector('[data-appearance-select]').onchange=e=>window.CartmanAppearance.apply(e.target.value);
 q('#basket-open').onclick=()=>basket();q('#address-open').onclick=()=>addressDialog();bindItems();window.CartmanMotion?.mount(document);
}
function home(){shell(`<section class="order-hero compact-order-hero"><div><h1>What do you need today?</h1><p>Meals, essentials, parcels, errands, and LIFT rides.</p></div><img src="${foodImage}" alt="Illustrative Filipino fried chicken, spaghetti and rice spread" width="800" height="520"></section><section class="browse"><div class="service-tabs" role="group" aria-label="Choose service">${[['all','home','All stores'],['lift','bike','Cartman LIFT'],['food','food','Food & drinks'],['grocery','bag','Groceries'],['parcel','box','Send a parcel'],['errands','bolt','Pabili'],['multi','orders','Multi-stop errands']].map(([key,i,t])=>`<button data-category="${key}" aria-pressed="${category===key}">${svg(i)}${t}</button>`).join('')}</div><div class="section-top discovery-title"><h2>${category==='food'?'Restaurants & cafés':category==='grocery'?'Groceries & tindahans':'Explore stores'}</h2><label class="search-box">${svg('search')}<input id="store-search" type="search" value="${esc(search)}" placeholder="Search stores or dishes" aria-label="Search stores or dishes"></label></div><div id="store-results" class="store-grid"></div></section>`);
 renderStores();document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{if(requestTypes.includes(b.dataset.category)){location.hash='/service/'+b.dataset.category;return}category=b.dataset.category;home()});q('#store-search').oninput=e=>{search=e.target.value;renderStores()};
}

function extraServiceCard(){const multi=category==='all';return `<a class="store-card service-discovery-card" href="#/service/${multi?'multi':'errands'}"><div class="store-photo"><img src="assets/${multi?'multi-errands-v2':'errands-branded'}.webp" alt="A collection of everyday shopping and parcels" width="600" height="380" loading="lazy"><span class="service-discovery-label">${multi?'MORE THAN ONE STOP?':'SOMETHING ELSE ON YOUR LIST?'}</span></div><div class="store-info"><div><h3>${multi?'Make a few stops. In one request.':'Tell us what you need.'}</h3><p>${multi?'Combine shopping, pickups and drop-offs.':'Plan a pabili request from your neighborhood store.'}</p></div><span class="store-arrow">↗</span></div><div class="store-meta"><span>${multi?'Multi-stop errands':'Pabili & errands'}</span><span>Plan a demo request</span></div></a>`}
function renderStores(){
 const needle=search.toLowerCase().trim();const found=stores.filter(s=>(category==='all'||category===s.type)&&(!needle||[s.name,s.tag,...s.items.map(i=>i[1])].join(' ').toLowerCase().includes(needle)));
 q('#store-results').innerHTML=found.length?found.map(s=>`<a class="store-card" href="#/store/${s.id}"><div class="store-photo"><img src="${s.image}" alt="Illustrative ${esc(s.category.toLowerCase())} photo" width="600" height="380" loading="lazy"></div><div class="store-info"><div><h3>${s.name}</h3><p>${s.tag}</p></div><span class="store-arrow">↗</span></div><div class="store-meta"><span>${s.category}</span><span>₱49 sample delivery</span></div></a>`).join(''):`<div class="empty"><h3>No stores found.</h3><p>Try a different dish, store name or category.</p><button class="secondary" id="reset-search">Reset filters</button></div>`;
 if(!needle&&found.length&&['all','grocery'].includes(category))q('#store-results').insertAdjacentHTML('beforeend',extraServiceCard());
 window.CartmanMotion?.refresh(q('#store-results'));
 if(q('#reset-search'))q('#reset-search').onclick=()=>{search='';category='all';home()};
}
function storePage(id){
 const s=stores.find(x=>x.id===id);if(!s){location.hash='/';return}
 shell(`<a class="back-link" href="#/">← Explore stores</a><section class="store-banner"><img src="${s.image}" alt="Illustrative food or essentials photo" width="1100" height="360"><div><span class="demo-pill">DEMO MENU</span><h1>${s.name}</h1><p>${s.tag}</p></div></section><div class="store-details"><span>${s.category}</span><span>₱49 sample delivery</span><span>25–40 min · simulated estimate</span></div><p class="disclosure">${s.note} All photos, items and prices below are illustrative.</p><div class="section-top"><div><span class="eyebrow">A LITTLE SOMETHING FOR YOUR DAY</span><h2>${s.type==='grocery'?'Shop the essentials':'On the menu'}</h2></div><span class="menu-item-count">${s.items.length} demo items</span></div><div class="menu-grid">${s.items.map(([id,name,price,description])=>`<article class="menu-card menu-card-visual"><div class="menu-product-image"><img src="${productImage(id)}" alt="Illustrative ${esc(name)}" width="400" height="400" loading="lazy" decoding="async"></div><div class="menu-product-content"><h3>${name}</h3><p>${description}</p><div class="menu-product-bottom"><strong>${peso(price)}</strong><button class="add-button" data-add="${id}" data-store="${s.id}" aria-label="Add ${name}">+</button></div></div></article>`).join('')}</div>`)
}
function bindItems(){document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const s=stores.find(s=>s.id===b.dataset.store),item=s.items.find(i=>i[0]===b.dataset.add),existing=cart.find(i=>i.id===item[0]);if(existing)existing.qty++;else cart.push({id:item[0],name:item[1],price:item[2],store:s.name,qty:1});persist('cart',cart);updateCount();notify(item[1]+' added to your basket.');b.textContent='✓';setTimeout(()=>{if(b.isConnected)b.textContent='+'},700)})}
function updateCount(){const b=q('#basket-open');b.setAttribute('aria-label',`Open basket, ${itemCount()} ${itemCount()===1?'item':'items'}`);const badge=b.querySelector('b'),previous=badge.textContent;badge.textContent=itemCount();if(previous!==badge.textContent&&!matchMedia('(prefers-reduced-motion: reduce)').matches)badge.animate([{transform:'scale(1)'},{transform:'scale(1.18)',offset:.5},{transform:'scale(1)'}],{duration:240,easing:'ease-out'});}
function openDialog(html,wide=false){const d=q('#app-dialog');d.className=wide?'basket-dialog':'';d.innerHTML=`<button class="dialog-close" aria-label="Close dialog">×</button>${html}`;d.querySelector('h2').id='dialog-heading';d.setAttribute('aria-labelledby','dialog-heading');d.querySelector('.dialog-close').onclick=()=>window.CartmanMotion.closeDialog(d);d.oncancel=event=>{event.preventDefault();window.CartmanMotion.closeDialog(d)};if(!d.open)d.showModal();return d}
function basket(){const d=openDialog(`<span class="eyebrow">YOUR LITTLE LIST OF GOOD THINGS</span><h2>Your basket <span class="count">${itemCount()}</span></h2>${cart.length?`<div class="basket-items">${cart.map(i=>`<article class="basket-item"><div class="basket-product"><img src="${productImage(i.id)}" alt="" width="64" height="64"><div><small>${esc(i.store)}</small><h3>${esc(i.name)}</h3><strong>${peso(i.price*i.qty)}</strong></div></div><div class="quantity"><button data-qty="${i.id}" data-delta="-1" aria-label="Remove one ${esc(i.name)}">−</button><span>${i.qty}</span><button data-qty="${i.id}" data-delta="1" aria-label="Add one ${esc(i.name)}">+</button></div></article>`).join('')}</div>${totals(subtotal())}<p class="disclosure">Demo pricing only. Your basket may include multiple sample stores.</p><a href="#/checkout" class="primary full" id="checkout-link">Continue to checkout ${svg('arrow')}</a>`:`<div class="empty">${svg('bag')}<h3>A little empty, for now.</h3><p>Find something you love and add it here.</p><button class="primary" id="explore-close">Explore stores</button></div>`}`,true);if(q('#explore-close'))q('#explore-close').onclick=()=>window.CartmanMotion.closeDialog(d);if(q('#checkout-link'))q('#checkout-link').onclick=()=>{serviceDraft=null;persist('service-draft',null);d.close()};document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const item=cart.find(i=>i.id===b.dataset.qty);item.qty+=Number(b.dataset.delta);cart=cart.filter(i=>i.qty>0);persist('cart',cart);updateCount();basket()})}
function totals(amount,service=false,label='Sample service fee'){return `<dl class="totals">${service?'':`<div><dt>Items subtotal</dt><dd>${peso(amount)}</dd></div>`}<div><dt>${service?label:'Sample delivery fee'}</dt><dd>${peso(service?amount:49)}</dd></div><div class="grand-total"><dt>Demo total</dt><dd>${peso(service?amount:amount+49)}</dd></div></dl>`}
function addressDialog(){const d=openDialog(`<span class="eyebrow">YOUR NEIGHBORHOOD, CONNECTED</span><h2>Where are we headed?</h2><p>This address personalizes the demo. Live coverage is not checked.</p><form id="address-form"><label>Delivery address<input name="address" required maxlength="180" autocomplete="street-address" value="${esc(delivery)}" placeholder="Building, street, barangay, city"></label><button class="primary full">Save delivery address</button></form>`);q('#address-form').onsubmit=e=>{e.preventDefault();delivery=new FormData(e.target).get('address').trim();if(!delivery)return;persist('address',delivery);d.close();render()}}
function servicePage(type){if(type==='lift')return liftPage();if(type==='multi')return multiPage();const parcel=type==='parcel';shell(`<a class="back-link" href="#/">← Explore services</a><div class="service-layout"><section><span class="eyebrow">${parcel?'ACROSS TOWN. WITH CARE.':'A HELPING HAND FOR YOUR TO-DO LIST.'}</span><h1>${parcel?'Send a parcel.<br>Across town.':'Pabili & errands.<br>Your list, covered.'}</h1><p class="lead">${parcel?'A document, a thoughtful gift, an everyday essential. Preview a door-to-door delivery.':'From Aling Neneng’s tindahan to the neighborhood bakery. Tell us what you need.'}</p><img class="service-illustration" src="assets/${parcel?'service-parcel':'errands-branded'}.webp" alt="${parcel?'Carefully packed parcels':'Everyday shopping in a Cartman tote'}"></section><form id="service-form" class="form-panel"><h2>${parcel?'Your parcel details':'Your pabili list'}</h2>${parcel?'':'<a class="errand-upgrade" href="#/service/multi">More than one stop? Plan multiple errands →</a>'}<label>${parcel?'Pickup address':'Store / pickup address'}<input name="pickup" placeholder="${parcel?'Building, street, barangay':'e.g. Aling Neneng’s, Barangay Central'}" maxlength="180" required></label><label>Delivery address<input name="dropoff" value="${esc(delivery)}" maxlength="180" required></label><label>${parcel?'What are you sending?':'What would you like us to buy?'}<textarea name="details" rows="4" maxlength="1000" required placeholder="${parcel?'Describe the parcel and handling instructions':'List each item and quantity. Example: 1 kg rice, 6 eggs.'}"></textarea></label>${parcel?'<label>Parcel size<select name="size"><option>Small · up to 3 kg</option><option>Medium · up to 5 kg</option></select></label>':'<label>Illustrative shopping budget (₱)<input type="number" name="budget" min="1" max="10000" step="1" required placeholder="e.g. 300"></label>'}<p class="disclosure">${parcel?'Sample fee ₱79.':'Sample service fee ₱89. Purchases are additional and are not charged in this demo.'} No real delivery will be requested.</p><button class="primary full">Review demo request ${svg('arrow')}</button></form></div>`);q('#service-form').onsubmit=e=>{e.preventDefault();serviceDraft={...Object.fromEntries(new FormData(e.target)),type,fee:parcel?79:89};persist('service-draft',serviceDraft);location.hash='/checkout'}}
function checkout(){if(!cart.length&&!serviceDraft){shell(`<div class="empty"><h1>Start with an order or service.</h1><p>Add an item or tell us which service you need.</p><a class="primary" href="#/">Explore Cartman</a></div>`);return}const s=serviceDraft;const amount=s?s.fee:subtotal();shell(`<a class="back-link" href="${s?'#/service/'+s.type:'#/'}">← Keep exploring</a><div class="section-top"><div><span class="eyebrow">A FEW DETAILS. ONE LESS ERRAND.</span><h1>Make it yours.</h1><p>Review your demo order and delivery details.</p></div><span class="demo-pill">NO PAYMENT REQUIRED</span></div><div class="checkout-layout"><form id="checkout-form" class="form-panel"><h2>${s?.type==='lift'?'Who’s taking the ride?':'Where should we bring it?'}</h2><label>${s?.type==='lift'?'Passenger name':'Recipient name'}<input name="name" autocomplete="name" maxlength="80" value="${esc(profile?.name||'')}" required placeholder="Juan dela Cruz"></label><label>Mobile number<input name="phone" type="tel" autocomplete="tel" inputmode="tel" pattern="[+0-9 ()-]{10,18}" maxlength="18" required placeholder="09XX XXX XXXX" value="${esc(profile?.phone||'')}"></label><label>Complete delivery address<textarea name="address" rows="2" maxlength="240" required>${esc(s?.dropoff||delivery)}</textarea></label><label>Delivery notes <span>(optional)</span><textarea name="notes" rows="2" maxlength="500" placeholder="Landmark, building entrance, or a little extra detail"></textarea></label><fieldset><legend>Demo payment method</legend><label class="radio"><input type="radio" name="payment" value="Cash on delivery" checked> Cash on delivery · simulated</label><label class="radio"><input type="radio" name="payment" value="GCash"> GCash · simulated, no account connection</label></fieldset><label class="checkbox"><input type="checkbox" required> I understand this is a demo. No purchase, payment, ride or delivery takes place.</label><button class="primary full">Place demo ${s?.type==='lift'?'ride':s?'request':'order'} ${svg('arrow')}</button></form><aside class="form-panel order-summary"><h2>Your ${s?'request':'order'}, at a glance.</h2>${s?requestDetails(s):cart.map(i=>`<div class="summary-item"><span class="summary-product"><img src="${productImage(i.id)}" alt="" width="48" height="48"><span>${i.qty} × ${esc(i.name)}<small>${esc(i.store)}</small></span></span><strong>${peso(i.price*i.qty)}</strong></div>`).join('')}${totals(amount,!!s,s?.type==='lift'?'Sample ride fare':'Sample service fee')}<p class="disclosure">Prices and fees are sample values. Confirmation saves an order only in this browser.</p></aside></div>`);q('#checkout-form').onsubmit=e=>{e.preventDefault();const details=Object.fromEntries(new FormData(e.target));const order={id:'CM-'+crypto.randomUUID().slice(0,8).toUpperCase(),date:new Date().toISOString(),details,items:s?[]:cart.map(i=>({...i})),service:s?{...s}:null,total:s?amount:amount+49,stage:0};orders.unshift(order);persist('orders',orders);if(!s){cart=[];persist('cart',cart)}serviceDraft=null;persist('service-draft',null);location.hash='/track/'+order.id}}
function ordersPage(){shell(`<div class="section-top"><div><span class="eyebrow">YOUR EVERYDAY, TAKEN CARE OF</span><h1>Your orders, rides & errands.</h1><p>Demo orders saved on this browser.</p></div><a class="primary" href="#/">Order something good ${svg('arrow')}</a></div>${orders.length?`<div class="order-list">${orders.map(o=>`<a href="#/track/${o.id}" class="order-row"><span class="order-icon">${svg(o.service?.type==='lift'?'bike':o.service?'box':'bag')}</span><div><h3>${o.id}</h3><p>${esc(o.service?requestName(o.service):o.items.map(i=>i.name).join(', '))}</p><small>${new Date(o.date).toLocaleDateString('en-PH')} · ${esc(o.details.address)}</small></div><span><b>${peso(o.total)}</b><small>${requestStatus(o)} · demo</small></span>${svg('arrow')}</a>`).join('')}</div>`:`<div class="empty">${svg('orders')}<h2>Your next little journey starts here.</h2><p>No demo orders yet. Find a favorite to get started.</p><a href="#/" class="primary">Explore stores</a></div>`}`,'orders')}
function tracking(id){const o=orders.find(o=>o.id===id);if(!o){ordersPage();return}if(o.service?.type==='multi')return multiTracking(o);const steps=o.service?.type==='lift'?['Ride request saved','Finding your driver','Ride in progress','Arrived at destination']:o.service?.type==='multi'?['Errands request saved','Preparing your route','Completing your stops','All errands complete']:['Demo order confirmed','Preparing your good things','On the way to you','A little doorstep happiness'];shell(`<a class="back-link" href="#/orders">← My orders</a><div class="section-top"><div><span class="eyebrow">${o.stage===0?'YOUR DEMO ORDER IS SAVED':'YOUR DELIVERY JOURNEY · SIMULATION'}</span><h1>${o.service?.type==='lift'?(o.stage===3?'You’ve arrived.':'Your ride, in view.'):o.service?.type==='multi'?(o.stage===3?'Errands done. Day made.':'Your errands, in view.'):(o.stage===3?'Delivered. Day made.':'Good things are coming.')}</h1><p>${o.id} · ${esc(o.details.name)}</p></div><span class="demo-pill">SIMULATED TRACKING</span></div><div class="tracking-layout"><section class="tracking-card"><img src="assets/cartman-app-icon.webp" width="80" height="80" alt="Cartman PH"><h2>${steps[o.stage]}</h2><p>No real driver is assigned. Use the button below to explore this simulated journey.</p><ol class="timeline">${steps.map((t,i)=>`<li class="${i<=o.stage?'complete':''}"><span>${i<o.stage?'✓':i+1}</span><div><strong>${t}</strong><small>${i===0?'Saved on this browser':i===1?(o.service?.type==='lift'?'Simulated driver matching':o.service?.type==='multi'?'Your chosen stop order':'Sample store preparation'):i===2?(o.service?.type==='lift'?'Simulated trip progress':'Simulated delivery progress'):'Demo complete'}</small></div></li>`).join('')}</ol>${o.stage<3?'<button class="primary full" id="advance-order">Simulate next step →</button>':'<a class="primary full" href="#/">Find your next favorite →</a>'}</section><aside class="form-panel"><h2>${o.service?.type==='lift'?'Ride details':'Delivery details'}</h2><p><strong>${esc(o.details.name)}</strong><br>${esc(o.details.phone)}</p><p>${esc(o.details.address)}</p><p>${esc(o.details.notes||'No additional delivery notes.')}</p><hr>${o.service?'':'<h3>Your basket</h3>'}${o.service?requestDetails(o.service):o.items.map(i=>`<p>${i.qty} × ${esc(i.name)} <small>· ${esc(i.store)}</small></p>`).join('')}<div class="total-line"><span>Demo total</span><strong>${peso(o.total)}</strong></div><p class="disclosure">${esc(o.details.payment)} · No payment collected.</p></aside></div>`,'orders');if(q('#advance-order'))q('#advance-order').onclick=()=>{o.stage++;persist('orders',orders);tracking(id);q('#main').focus({preventScroll:true})}}
function account(){shell(`<div class="profile-layout"><section><span class="eyebrow">YOUR LITTLE CORNER OF CARTMAN</span><h1>${profile?'Hello, '+esc(profile.name.split(' ')[0])+'.':'A more personal everyday.'}</h1><p class="lead">Save your details on this browser for an easier demo checkout. You can also order as a guest.</p><a class="pill-link" href="#/orders">See your demo orders ${svg('arrow')}</a></section><form id="profile-form" class="form-panel"><h2>Your demo profile</h2><label>Name<input name="name" autocomplete="name" value="${esc(profile?.name||'')}" maxlength="80" required></label><label>Mobile number<input name="phone" type="tel" autocomplete="tel" pattern="[+0-9 ()-]{10,18}" maxlength="18" value="${esc(profile?.phone||'')}" required></label><p class="disclosure">This is a local profile, without server authentication. Your details stay in this browser.</p><button class="primary full">Save profile</button></form></div>`,'user');q('#profile-form').onsubmit=e=>{e.preventDefault();profile=Object.fromEntries(new FormData(e.target));persist('profile',profile);account();notify('Your demo profile is saved.')};}
function render(){const parts=(location.hash.slice(1)||'/').split('/').filter(Boolean);document.title=(parts[0]==='store'?stores.find(s=>s.id===parts[1])?.name||'Store':parts[0]==='checkout'?'Checkout':parts[0]==='orders'?'My orders':'Order online')+' · Cartman PH';if(parts[0]==='store')storePage(parts[1]);else if(parts[0]==='service'&&requestTypes.includes(parts[1]))servicePage(parts[1]);else if(parts[0]==='checkout')checkout();else if(parts[0]==='orders')ordersPage();else if(parts[0]==='track')tracking(parts[1]);else if(parts[0]==='account')account();else{const initial=location.hash?null:new URLSearchParams(location.search).get('service');if(!parts.length&&initial&&['food','grocery'].includes(initial))category=initial;if(!parts.length&&requestTypes.includes(initial)){servicePage(initial);return}home()}}
addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});q('#main')?.focus({preventScroll:true})});render();
